			Class<?> backing = base ? AbstractLiteral.immutableNumericRepresentation(literal)
					: NumericLiteral.immutableNumericRepresentation((NumericLiteral) literal);
			NumericTag tag = backing == Byte.class ? NumericTag.BYTE
					: backing == Short.class ? NumericTag.SHORT
							: backing == Integer.class ? NumericTag.INTEGER
									: backing == Long.class ? NumericTag.LONG
											: backing == Float.class ? NumericTag.FLOAT
													: backing == Double.class ? NumericTag.DOUBLE : null;
			if (tag == null) {
				return null;
			}
